Compute a running total where each year’s end wealth is (previous total + that year’s deposit) × (1 + that year’s efficiency). Ignore inflation and the per-deposit helper columns. Write the rounded running totals as plain values into H2:H40.

```python
import shutil
import openpyxl
from decimal import Decimal, ROUND_HALF_UP

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def to_decimal(value):
    if value is None:
        return Decimal("0")
    if isinstance(value, bool):
        return Decimal("1") if value else Decimal("0")
    return Decimal(str(value))

total = Decimal("0")

for row in range(2, 41):
    deposit = to_decimal(vws.cell(row=row, column=2).value)
    efficiency = to_decimal(vws.cell(row=row, column=3).value)

    total = (total + deposit) * (Decimal("1") + efficiency)
    ws.cell(row=row, column=8).value = float(
        total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    )

wb.save(OUT)

print("Answer sheet:", ws.title)
for row in (2, 3, 4, 5):
    print(row, ws.cell(row=row, column=8).value)
